import {
	Component,
	Element,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";
import { focusVisible } from "../../utils/focus-visible";
import { generateShortID } from "../../utils/function-helper";
import { getCssRulesForSentimentIconButton } from "../../utils/sentiments";

/**
 * @since 2.0
 * @status stable
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-icon-button",
	styleUrl: "icon-button.scss",
	shadow: true,
})
export class IconButton {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	button: HTMLButtonElement;
	@Element() host: HTMLHbrIconButtonElement;

	/** Raw svg source code as string */
	@Prop({ reflect: false }) asset: string | (() => string);

	/** The name of the icon to draw. */
	@Prop({ reflect: true }) name: string;

	/** Size of the icon, by default icons are sized relative to the current font size */
	@Prop() size: string;

	/** Width of the icon, takes priority over size and css font-size. Set this prop when width and height are not same.*/
	@Prop() width: string;

	/** Height of the icon, takes priority over size and css font-size. Set this prop when width and height are not same. */
	@Prop() height: string;

	/** An alternative description to use for accessibility. If omitted, the name or src will be used to generate it. */
	@Prop() label: string;

	/** A list of Colors for the paths*/
	@Prop() colors: Array<string>;

	/** Retain static colors hardcoded in the svg file instead of replace them with css properties by default */
	@Prop({ reflect: true }) staticColors = false;

	/** Icon being used as informative image. Deprecate candidate. Use "aria={label: value}" instead. */
	@Prop() arialabel = "";

	/** Attributes related to screen readers. */
	@Prop() aria: { label: string };

	/** The name of a registered custom icon library. */
	@Prop({ reflect: true }) library: string;

	/** An external URL of an SVG file. */
	@Prop({ reflect: true }) src: string;

	/** Set to true to disable the button. */
	@Prop({ reflect: true }) disabled = false;

	/** The icon-button's sentiment. */
	@Prop({ reflect: true }) sentiment:
		| "interact"
		| "success"
		| "neutral"
		| "info"
		| "warning"
		| "danger";

	/** remove spacing around the icon */
	@Prop({ reflect: true }) noPadding: boolean;

	/** Tooltip content if the icon button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip: string;

	@State() tooltipId = `tooltip-${generateShortID()}`;

	/** Focuses the icon button. */
	@Method()
	async setFocus() {
		this.button.focus();
	}

	componentDidLoad() {
		if (this.button) {
			focusVisible.observe(this.button);
		}
	}

	disconnectedCallback() {
		if (this.button) {
			focusVisible.unobserve(this.button);
		}
	}

	render() {
		if (this.sentiment && this.host) {
			this.sheet.replaceSync(`
				${getCssRulesForSentimentIconButton({
					sentiment: this.sentiment,
					disabled: this.disabled,
				})}
				.icon-button:hover {
					${getCssRulesForSentimentIconButton({
						sentiment: this.sentiment,
						disabled: this.disabled,
						type: "hover",
					})}
				}
			`);
			addConstructedStyle(this.host.shadowRoot, this.sheet);
		}

		return (
			<Host>
				<button
					ref={(el) => {
						this.button = el;
					}}
					part="base"
					class={{
						"icon-button": true,
						"icon-button--disabled": this.disabled,
						"icon-button--no-padding": this.noPadding,
					}}
					type="button"
					role="button"
					aria-label={this.aria?.label || this.arialabel || `${this.name}`}
					aria-describedby={this.tooltip ? this.tooltipId : null}
					disabled={this.disabled}
					aria-disabled={this.disabled ? "true" : null}
					{...this.aria}
				>
					<hbr-icon
						library={this.library}
						asset={this.asset}
						name={this.name}
						src={this.src}
						size={this.size}
						width={this.width}
						height={this.height}
						label={this.label}
						colors={this.colors}
						sentiment={this.sentiment}
						staticColors={this.staticColors}
						exportparts="base:icon-base"
					/>
				</button>
				<span id={this.tooltipId} hidden>
					{this.tooltip}
				</span>
			</Host>
		);
	}
}
